70	const BLOCK_SIZE = 3;
71	const COMPONENT_BLOCK_PREMIUM = 60;
72	
73	const COMPONENT_TYPES = ["rune", "moonstone"];
74	
75	const componentBlockAdjustment = (
76	  items: Item[],
77	  componentType: string,
78	): number => {
79	  const count = items.filter((item) => item.type === componentType).length;
80	  return count === BLOCK_SIZE
81	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
82	    : 0;
83	};
