85	const basePremiumFor = (items: Item[]): number =>
86	  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
87	  COMPONENT_TYPES.reduce(
88	    (total, componentType) => total + componentBlockAdjustment(items, componentType),
89	    0,
90	  );
91	
92	const surchargeFor = (
93	  items: Item[],
94	  rate: number,
95	  applies: (item: Item) => boolean,
96	): number =>
97	  items.reduce(
98	    (total, item) =>
99	      total + (applies(item) ? rate * BASE_PREMIUMS[item.type] : 0),
100	    0,
101	  );
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	const curseSurchargeFor = (items: Item[]): number =>
109	  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);
110	
111	const highEnchantmentSurchargeFor = (items: Item[]): number =>
112	  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
113	
114	const quotePremium = (
115	  items: Item[],
116	  customer: Customer,
117	  isFollowUpContract: boolean,
118	): number => {
119	  const basePremium = basePremiumFor(items);
120	  const itemSurcharges =
121	    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
122	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
123	  const loyaltyDiscount =
124	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
125	      ? basePremium * LOYALTY_DISCOUNT_RATE
126	      : 0;
127	  const followUpDiscount = isFollowUpContract
128	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
129	    : 0;
130	  return Math.ceil(
131	    basePremium +
132	      itemSurcharges +
133	      firstInsuranceSurcharge -
134	      loyaltyDiscount -
135	      followUpDiscount +
136	      PROCESSING_FEE,
137	  );
138	};
