148	const claimResult = (
149	  claimStep: ClaimStep,
150	  policyItems: Item[],
151	): ClaimResult => {
152	  const payout = claimStep.incident.damages.reduce(
153	    (total, damage) => total + (damage.amount - DEDUCTIBLE_PER_DAMAGE),
154	    0,
155	  );
156	  const insuranceSum = policyItems.reduce(
157	    (total, item) => total + INSURANCE_VALUES[item.type],
158	    0,
159	  );
160	  const cap = PAYOUT_CAP_MULTIPLIER * insuranceSum;
161	  return { payout, remainingCap: cap - payout };
162	};
