164	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
165	  results: scenario.steps.map((step, index) => {
166	    if (step.op === "claim") {
167	      const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
168	      return claimResult(step, policyItems);
169	    }
170	    return {
171	      premium: quotePremium(step.items, scenario.customer, index > 0),
172	    };
173	  }),
174	});
